{
  "hooks_totales": [
    {
      "noticia": "Seguridad ferroviaria y fallos en Alta Velocidad: cadena de decisión y supervisión",
      "tipo": "incredulidad / revelación",
      "hook": "¿Cómo puede circular un tren con seguridad desactivada sin que alguien lo “autorice” en algún punto?",
      "guion": "Empieza con la pregunta: si la seguridad podía estar desactivada y aun así circular, entonces no era un accidente cualquiera. Presenta el tema como arquitectura de responsabilidad: normas, calendario de decisiones, controles y tolerancia al riesgo. Cierra prometiendo el mapa de “quién decide” frente al “quién lo operó”."
    },
    {
      "noticia": "Seguridad ferroviaria y fallos en Alta Velocidad: cadena de decisión y supervisión",
      "tipo": "contradicción / desactivación del relato",
      "hook": "“Fallo técnico” dicen… pero cuando el sistema puede ir apagado, ya no hablamos de azar: hablamos de rutina.",
      "guion": "Replica el marco mediático (proceso/operaciones) y lo desmonta: cuando algo sucede lo suficiente como para ser plausible, deja de ser evento aislado. Afirma que el encuadre que evita nombrar responsables es humo. Remata con la frase: el problema es decisión convertida en hábito."
    },
    {
      "noticia": "Seguridad ferroviaria y fallos en Alta Velocidad: cadena de decisión y supervisión",
      "tipo": "promesa de investigación",
      "hook": "Te cuentan lo que pasó… pero faltan las preguntas que señalan a los que firmaron los controles.",
      "guion": "Marca el contraste entre “cronología de hechos” y “cronología de responsabilidades”. Lista 3–4 preguntas tipo (quién autorizó, quién supervisó, qué tolerancia al riesgo existía, qué falló en el control). Anuncia que el vídeo/guion mostrará esa cascada."
    },
    {
      "noticia": "Seguridad ferroviaria y fallos en Alta Velocidad: cadena de decisión y supervisión",
      "tipo": "emocional / víctimas como centro",
      "hook": "No es un titular: es la ciudadanía intentando entender por qué el sistema falló antes de que el daño fuera noticia.",
      "guion": "Abre con el punto de vista de familiares/usuarios. Conecta el desconocimiento del público con la estrategia de difuminar culpables. Promete pasar del “caso” a la mecánica: cómo se llega a que el riesgo llegue puntualmente a su estación."
    },
    {
      "noticia": "Seguridad ferroviaria y fallos en Alta Velocidad: cadena de decisión y supervisión",
      "tipo": "sarcástico / llamada a la coherencia",
      "hook": "Claro: es solo “gestión”, solo “proceso”, solo “fallo sistémico”… ¿y entonces quién dejó el botón apagado?",
      "guion": "Usa sarcasmo para forzar al espectador a pensar en nombres y decisiones. Remata: nadie señala quién firmó el control, quién miró hacia otro lado y quién hizo que el riesgo llegara a tiempo."
    },
    {
      "noticia": "Seguridad ferroviaria y fallos en Alta Velocidad: cadena de decisión y supervisión",
      "tipo": "marco cognitivo / sesgo mediático",
      "hook": "La noticia te da emoción… pero te quita la causa. ¿Te han enseñado el mecanismo o solo el impacto?",
      "guion": "Explica en una frase la alternancia catastrofismo/neutralización. Menciona que un bando activa alarma y el otro enfriar el golpe (conductores, investigación parcial). Afirma que así se evita “quién decidió”."
    },
    {
      "noticia": "Seguridad ferroviaria y fallos en Alta Velocidad: cadena de decisión y supervisión",
      "tipo": "cambio de enfoque / “no hay misterio”",
      "hook": "No hay misterio: hay arquitectura. Si hay desactivación, hay diseño, controles y tolerancia al riesgo.",
      "guion": "Abre con la tesis “no hay misterio”. Divide en 3 piezas: entorno normativo, calendario de decisiones, cadena de supervisión. Cierra invitando a seguir el rastro para ver quién queda fuera del encuadre."
    },
    {
      "noticia": "Violencia en Tarragona (marco de investigación policial y cierre del debate social)",
      "tipo": "angustia / quién controla el marco",
      "hook": "¿Quién decide qué se puede preguntar cuando empieza la investigación policial?",
      "guion": "Señala el marco que cierra el debate social “en el perímetro de la noticia”. Propón una reflexión: investigar no debería silenciar el porqué social. Promete separar hechos de la forma de contarlos."
    },
    {
      "noticia": "Violencia en Tarragona (marco de investigación policial y cierre del debate social)",
      "tipo": "humanización / “no es un caso”",
      "hook": "Cuando lo convierten en ‘caso’, pierdes a la persona. ¿Por qué nos piden que miremos sin sentir?",
      "guion": "Arranca con el riesgo de deshumanizar: personas reducidas a expediente. Enfoca que también se puede (y debe) contar sin convertir a víctimas en un trámite. Anuncia que el guion devuelve humanidad y contexto."
    },
    {
      "noticia": "Violencia en Tarragona (marco de investigación policial y cierre del debate social)",
      "tipo": "tensión / debate truncado",
      "hook": "Si el debate se cierra con el ‘modo investigación’, ¿quién se queda sin preguntas?",
      "guion": "Plantea que el marco policial puede ser necesario, pero también puede tapar el debate social. Sugiere que faltan dimensiones: prevención, contexto, responsabilidades. Cierra con invitación a abrir la conversación sin linchamientos."
    },
    {
      "noticia": "Violencia en Tarragona (marco de investigación policial y cierre del debate social)",
      "tipo": "cambio de lente / del suceso al sistema",
      "hook": "No basta con “resolver quién”. También hay que preguntar “por qué” volvió a pasar.",
      "guion": "Conecta con el patrón del día: procesos que desplazan causas. Explica que una investigación puede responder al autor, pero no al mecanismo social. Propón un enfoque preventivo y de gestión pública."
    },
    {
      "noticia": "Violencia en Tarragona (marco de investigación policial y cierre del debate social)",
      "tipo": "contranarrativa / vigilancia del discurso",
      "hook": "La investigación te informa… pero el encuadre te educa para no exigir cambios. O al revés.",
      "guion": "Presenta la diferencia entre informar y usar el marco para neutralizar el debate. Explica cómo el relato puede convertirse en “final” en vez de “inicio”. Invita a escuchar con espíritu crítico."
    },
    {
      "noticia": "Violencia en Tarragona (marco de investigación policial y cierre del debate social)",
      "tipo": "pregunta incómoda / responsabilidad social",
      "hook": "¿Qué falló antes de que la violencia entrara en un hospital como si fuera parte del paisaje?",
      "guion": "Provoca una pregunta sistémica: prevención, protocolos, gestión, recursos. Evita el morbo y centra el “antes”. Promete repasar qué se suele contar y qué se suele omitir."
    },
    {
      "noticia": "Caída del Ibex / mercado y despidos en el sector financiero (BBVA, Sabadell, ING)",
      "tipo": "normalización del dolor / crítica de propaganda",
      "hook": "Te lo venden como ‘éxito financiero’… y lo llaman ajuste cuando afecta a personas.",
      "guion": "Enuncia la neutralización: cifras, tono de mercado, despidos como inevitable. Contrapón la lectura: son decisiones con ganadores y perdedores. Cierra señalando que “progreso” sin costes humanos es propaganda."
    },
    {
      "noticia": "Caída del Ibex / mercado y despidos en el sector financiero (BBVA, Sabadell, ING)",
      "tipo": "cifras contra humanidad",
      "hook": "¿Cuántas vidas se convierten en un porcentaje cuando el titular habla de caídas bursátiles?",
      "guion": "Pone el foco en el contraste entre el lenguaje: Ibex/porcentajes vs. familias/empleos. Resume el sesgo hacia la racionalidad financiera. Promete “traducir” cifras a impacto humano."
    },
    {
      "noticia": "Caída del Ibex / mercado y despidos en el sector financiero (BBVA, Sabadell, ING)",
      "tipo": "desmontaje de inevitabilidad",
      "hook": "“Es inevitable”, dicen… pero nadie pronuncia la palabra clave: decisiones.",
      "guion": "Ataca el marco de inevitabilidad (“corrección”, “outlook”). Reubica el debate en el terreno político/empresarial de la decisión. Cierra con la idea: lo que parece inevitable es planificado."
    },
    {
      "noticia": "Caída del Ibex / mercado y despidos en el sector financiero (BBVA, Sabadell, ING)",
      "tipo": "contradicción / éxito sin relato de costes",
      "hook": "Cuando el mercado sube, todo es narrativa… cuando la gente pierde el trabajo, todo es estadística.",
      "guion": "Explica la asimetría del encuadre: emoción y relato en un lado; neutralización y frialdad en el otro. Une tren + violencia + bolsa como patrón mediático de dispersión y difuminado de culpa."
    },
    {
      "noticia": "Caída del Ibex / mercado y despidos en el sector financiero (BBVA, Sabadell, ING)",
      "tipo": "ganadores/perdedores",
      "hook": "La bolsa no “cae” sola: hay decisiones, prioridades y un reparto de costes. ¿Quién paga realmente?",
      "guion": "Introduce la noción de reparto. Plantea que el discurso de mercado borra responsabilidades. Promete preguntar por el destino de beneficios, el motivo del recorte de empleos y la cadena de decisión interna."
    },
    {
      "noticia": "Caída del Ibex / mercado y despidos en el sector financiero (BBVA, Sabadell, ING)",
      "tipo": "sarcasmo / llamada a mirar al sujeto",
      "hook": "Claro, claro: solo era “recorte”. Nadie dijo que también era desempleo con nombre y apellidos.",
      "guion": "Usa el sarcasmo para denunciar la eufemización. Conecta con el patrón del día: catastrofismo o neutralización, pero siempre con la responsabilidad difuminada. Cierra invitando a recuperar nombres y efectos."
    }
  ]
}
